<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);$uid=(int)user()['id'];$stmt=$con->prepare('SELECT name,email,phone,education_level,date_of_birth,resume_path,resume_updated_at FROM users WHERE id=?');$stmt->bind_param('i',$uid);$stmt->execute();$profile=$stmt->get_result()->fetch_assoc();$stmt=$con->prepare('SELECT * FROM user_education WHERE user_id=? ORDER BY is_current DESC,end_year DESC,start_year DESC');$stmt->bind_param('i',$uid);$stmt->execute();$education=$stmt->get_result();$pageTitle='My profile';require dirname(__DIR__).'/includes/header.php';?>
<div class="container py-5" style="max-width:1000px"><div class="mb-4"><h1>My career profile</h1><p class="text-muted">Keep your resume and education background ready for job applications.</p></div><div class="row g-4"><div class="col-lg-5"><div class="card p-4 h-100"><div class="d-flex align-items-center gap-3 mb-3"><span class="profile-document-icon"><i class="bi bi-file-earmark-person"></i></span><div><h2 class="h5 mb-1">Resume</h2><small class="text-muted"><?=$profile['resume_updated_at']?'Updated '.e($profile['resume_updated_at']):'No resume uploaded'?></small></div></div><?php if($profile['resume_path']):?><a class="btn btn-outline-primary mb-3" target="_blank" href="<?=url($profile['resume_path'])?>"><i class="bi bi-eye"></i> View current resume</a><?php endif?><form action="<?=url('ajax/resume_upload.php')?>" method="post" enctype="multipart/form-data" data-ajax><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label"><?=$profile['resume_path']?'Replace resume':'Upload resume'?></label><input class="form-control mb-2" type="file" name="resume" accept=".pdf,.doc,.docx" required><div class="form-text mb-3">PDF, DOC, or DOCX · maximum 5 MB</div><button class="btn btn-primary w-100"><i class="bi bi-upload"></i> <?=$profile['resume_path']?'Update resume':'Upload resume'?></button></form></div></div>
<div class="col-lg-7"><div class="card p-4"><div class="d-flex justify-content-between align-items-start mb-3"><div><h2 class="h5 mb-1">Education background</h2><p class="small text-muted mb-0">Add qualifications, courses, and current study.</p></div><button class="btn btn-sm btn-primary" data-bs-toggle="modal" data-bs-target="#educationModal"><i class="bi bi-plus-circle"></i> Add education</button></div><?php if(!$education->num_rows):?><div class="empty-profile-state">No education records added yet.</div><?php endif?><?php foreach($education as $item):?><div class="education-item"><div><strong><?=e($item['qualification'])?></strong><div><?=e($item['institution'])?></div><small><?=e($item['field_of_study'])?> · <?=$item['start_year']?>–<?=$item['is_current']?'Present':$item['end_year']?></small></div><button class="btn btn-sm btn-outline-primary edit-education" data-row='<?=e(json_encode($item))?>'>Edit</button></div><?php endforeach?></div></div></div></div>
<div class="modal fade" id="educationModal"><div class="modal-dialog"><form class="modal-content" action="<?=url('ajax/education_save.php')?>" method="post" data-ajax><div class="modal-header"><h2 class="modal-title fs-5">Education background</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id"><label class="form-label">Institution</label><input class="form-control mb-3" name="institution" required><label class="form-label">Qualification</label><input class="form-control mb-3" name="qualification" required><label class="form-label">Field of study</label><input class="form-control mb-3" name="field_of_study"><div class="row g-3"><div class="col-6"><label class="form-label">Start year</label><input type="number" class="form-control" name="start_year" min="1950" max="<?=date('Y')+1?>" required></div><div class="col-6"><label class="form-label">End year</label><input type="number" class="form-control" name="end_year" min="1950" max="<?=date('Y')+10?>"></div></div><label class="form-check mt-3"><input class="form-check-input" type="checkbox" name="is_current"> I am currently studying here</label></div><div class="modal-footer"><button type="button" class="btn btn-outline-danger d-none" id="deleteEducation">Delete</button><button class="btn btn-primary">Save education</button></div></form></div></div>
<script>document.querySelectorAll('.edit-education').forEach(button=>button.onclick=()=>{const row=JSON.parse(button.dataset.row),form=document.querySelector('#educationModal form');Object.keys(row).forEach(key=>{if(form.elements[key])form.elements[key].type==='checkbox'?form.elements[key].checked=+row[key]===1:form.elements[key].value=row[key]??''});deleteEducation.classList.remove('d-none');bootstrap.Modal.getOrCreateInstance(educationModal).show()});educationModal.addEventListener('hidden.bs.modal',()=>{const form=document.querySelector('#educationModal form');form.reset();form.elements.id.value='';deleteEducation.classList.add('d-none')});deleteEducation.onclick=()=>{const form=document.querySelector('#educationModal form'),input=document.createElement('input');input.type='hidden';input.name='delete';input.value='1';form.append(input);form.requestSubmit()};</script><?php require dirname(__DIR__).'/includes/footer.php';?>
